function chapterButtons(){return moments.map(m=>`<button class="chapter-button ${state.event===m.id?'selected':''}" data-event="${m.id}" aria-pressed="${state.event===m.id}"><span class="chapter-index">${m.number}</span><span><h3>${m.title}</h3><p>${m.phase} · ${m.drivers}</p></span>${icon('chevron-right')}</button>`).join('');}
function renderMoment(){if(state.race!=='spain')return renderArchiveMoment();const m=moments.find(m=>m.id===state.event);$('#page-moments').innerHTML=heading('THE TURNING POINTS','看见精彩瞬间背后的选择。','把一个精彩瞬间，拆成能理解的三个问题。',`<label class="reading-mode"><input id="beginner-toggle" type="checkbox" ${state.beginner?'checked':''}>新手解释</label>`)+`<div class="two-col"><article class="panel"><div class="panel-title"><span class="chip ${m.color}">${m.phase} / ${m.drivers}</span><button class="icon-button bookmark-button" data-bookmark="${m.id}" aria-label="${bookmarks.includes(m.id)?'取消收藏':'收藏赛点'}" aria-pressed="${bookmarks.includes(m.id)}">${icon('bookmark')}</button></div><h2 class="moment-detail-title">${m.title}</h2><div class="stack section-space"><div class="evidence-row"><h3><span class="mini-label fact">事实</span> 发生了什么</h3><p>${m.fact}</p></div><div class="evidence-row"><h3><span class="mini-label analysis">解读</span> 为什么值得看</h3><p>${m.why}</p></div><div class="evidence-row"><h3><span class="mini-label scenario">假设</span> 换一种选择呢</h3><p>${m.alternative}</p></div></div>${state.beginner?`<div class="explain-box"><strong>第一次看 F1？</strong><br>${m.beginner}</div>`:''}<div class="action-row"><button class="button primary" data-view="${m.id==='vsc'?'strategy-research':'3d'}" ${m.id==='vsc'?'data-open-case="true"':''}>${icon(m.id==='vsc'?'git-branch':'box')}${m.id==='vsc'?'亲自改一次策略':'侧面看一次双车攻防'}</button><button class="button" data-view="overview">返回全场概览</button></div><p class="caption">事实依据：${source(m.key==='team'?'McLaren 赛后报告':'官方赛事报告',m.key)} · 解读不代表车队内部决策记录。</p></article><aside class="column"><div class="chapter-list">${chapterButtons()}</div><div class="panel"><span class="eyebrow">A BETTER QUESTION</span><h3>当时知道什么，比最后赢没赢更重要。</h3><p class="body-copy section-space">先回到那个时刻的限制，再判断选择。把“结果不好”和“决策错误”分开，才是有价值的复盘。</p></div></aside></div>`;}
