function renderDrivers(){if(state.race!=='spain')return renderArchiveDrivers();const d=drivers.find(x=>x.id===state.driver),c=drivers.find(x=>x.id===state.compare);$('#page-drivers').innerHTML=heading('DRIVER INTELLIGENCE','车手数据，放回比赛里看。','2026 西班牙大奖赛 · 官方完赛结果')+`<div class="two-col driver-layout"><div class="panel"><div class="panel-title"><h2>正赛分类</h2>${source('FIA 官方结果')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>POS</th><th>DRIVER / TEAM</th><th>GAP</th></tr></thead><tbody>${drivers.map(x=>`<tr class="${x.id===d.id?'selected':''}"><td>${String(x.pos).padStart(2,'0')}</td><td><button class="driver-select driver-cell" data-driver="${x.id}" aria-label="查看 ${x.name}" style="--driver-color:${x.color}"><i class="driver-swatch"></i><span><strong>${x.name}</strong><span>${x.team}</span></span></button></td><td>${x.gap}</td></tr>`).join('')}</tbody></table></div></div><div class="column"><div class="panel"><div class="driver-profile" style="--driver-color:${d.color}"><div class="driver-number">${String(d.pos).padStart(2,'0')}</div><div><span class="eyebrow">RACE POSITION / ${d.id}</span><h2>${d.name}</h2><p>${d.team}</p></div></div><div class="stat-grid"><div class="stat"><span>完赛状态</span><strong>${d.gap==='DNF'?'DNF':'P'+d.pos}</strong></div><div class="stat"><span>完成圈数</span><strong>${d.laps}<small>圈</small></strong></div><div class="stat"><span>比赛总圈数</span><strong>57<small>圈</small></strong></div></div><div class="race-fact-list section-space"><div><span>轮胎逐段与胎龄</span><strong>尚未接入</strong></div><div><span>实时功率 / 下压力</span><strong>未获得公开实测值</strong></div><div><span>引擎与能量部署</span><strong>未接入车载数据</strong></div></div><p class="caption">不把车型宣传参数当作当圈实测。比赛结果已接入本 Demo，车辆状态在下方展示交互形式。</p></div><div class="panel"><div class="panel-title"><h2>这一弯，差在哪里？</h2><span class="chip orange">演示遥测</span></div><div class="select-row"><label for="compare-driver">${d.id} 对比</label><select id="compare-driver" class="select">${drivers.filter(x=>x.id!==d.id).map(driverOption).join('')}</select></div><div class="chart-legend"><span style="--driver-color:${d.color}"><i class="chart-dot"></i>${d.id}</span><span style="--driver-color:${c.color}"><i class="chart-dot"></i>${c.id}</span><span>速度 / km/h</span></div><div id="telemetry-chart"></div><div class="source-note orange">曲线为合成示例，用于展示“刹车—弯心—出弯”的对比方式，不代表这些车手在本场的实际速度。</div><div class="action-row"><button class="button" data-view="3d">${icon('box')}把距离变化放进 3D</button></div></div></div></div>`;$('#compare-driver').value=state.compare;renderChart(d,c);}
function renderChart(d,c){const values=(index)=>Array.from({length:41},(_,i)=>{const x=i/40;return 292-168*Math.exp(-Math.pow((x-.47-(index%4)*.008)/.22,2))+(index%3)*4*Math.sin(x*8);});const path=arr=>arr.map((v,i)=>`${i?'L':'M'}${44+i*11.8},${178-(v-90)*.58}`).join(' ');$('#telemetry-chart').innerHTML=`<svg class="chart" viewBox="0 0 550 235" role="img" aria-label="合成速度曲线，展示两辆赛车刹车和出弯的对比，不是实测"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${d.color}" stop-opacity=".18"/><stop offset="1" stop-color="${d.color}" stop-opacity="0"/></linearGradient></defs>${[100,200,300].map(v=>`<path d="M44 ${178-(v-90)*.58}H523" stroke="#2a3542" stroke-dasharray="4 5"/><text x="7" y="${182-(v-90)*.58}">${v}</text>`).join('')}<path d="${path(values(d.pos))}L516 185H44Z" fill="url(#chart-fill)"/><path d="${path(values(d.pos))}" stroke="${d.color}" stroke-width="3" fill="none"/><path d="${path(values(c.pos))}" stroke="${c.color}" stroke-width="2.5" stroke-dasharray="6 4" fill="none"/><text x="47" y="218">刹车区</text><text x="257" y="218">弯心</text><text x="472" y="218">出弯</text></svg>`;}
const optionNames=['下一圈进站','再延后一圈','再延长三圈'];
function simulate(){const {deg:d,traffic:t,trafficFactor:f}=state;return [21.2+t,21.2+d+t*f,21.2+6*d+t*f*f];}
function renderStrategyCase(){if(state.race!=='spain')return renderArchiveStrategy();$('#strategy-cases').innerHTML=caseHeading('精选案例','回到那一刻，这次由你来选。','案例：Norris 错过 VSC 进站窗口之后',`<span class="chip orange">假设推演 / DEMO</span>`)+`<div class="source-note">决策起点：Norris 已经过进站入口。“VSC 刚出现就进站”已不可执行。下面比较的是此后仍可能采取的选择。</div><div class="two-col section-space"><div class="column"><article class="panel"><div class="panel-title"><h2>01 / 选择一条策略</h2><button class="text-button" data-action="reset-strategy">${icon('rotate-ccw')}重置</button></div><div class="option-grid">${optionNames.map((s,i)=>`<button class="strategy-option ${state.option===i?'selected':''}" data-option="${i}" aria-pressed="${state.option===i}"><span>${i===0?'实际时机 · 比较基准':'WHAT IF / 0'+i}</span><strong>${s}</strong><small>${['尽快结束旧胎阶段','观察一圈后的交通','继续利用现有轮胎'][i]}</small></button>`).join('')}</div><div class="slider-group"><div><label class="range-label" for="deg-slider">旧胎每多跑一圈的额外损失<strong id="deg-value"></strong></label><input id="deg-slider" class="range" type="range" min="0.1" max="2" step="0.1" value="${state.deg}"><p class="caption">损失随延后圈数累加；并非本场轮胎实测。</p></div><div><label class="range-label" for="traffic-slider">立即进站后的交通损失<strong id="traffic-value"></strong></label><input id="traffic-slider" class="range" type="range" min="0" max="8" step="0.5" value="${state.traffic}"></div><div class="select-row"><label for="traffic-evolution">继续等待后，交通如何变化？</label><select class="select" id="traffic-evolution"><option value="0.4">改善 · 剩余损失降至 40%</option><option value="1">不变 · 仍为 100%</option><option value="1.4">恶化 · 增至 140%</option></select></div></div></article><article class="panel"><div class="panel-title"><h2>02 / 当时为什么这样判断？</h2><span class="chip blue">公开信息</span></div><div class="stack"><div class="evidence-row"><h3>已知：入口已经错过</h3><p>这个空间限制不能靠“更果断”改变。回到入口之前，无法直接进行换胎。</p></div><div class="evidence-row"><h3>取舍：旧胎损失 vs. 回场交通</h3><p>继续等待有机会换来更清晰的赛道，也会增加旧胎成本。哪一项更大，决定了延后的价值。</p></div><div class="evidence-row"><h3>未知：下一次中断会不会发生</h3><p>复盘不能把之后才发生的事情，假设成当时策略组已经知道的信息。</p></div></div><p class="caption">${source('McLaren 赛后报告','team')} · 上述解释是基于公开信息的分析。</p></article></div><aside class="column"><article class="panel simulation-result" aria-live="polite"><div class="panel-title"><div><span class="eyebrow lime">THE COST OF A CHOICE</span><h2>换一种选择，代价怎么变？</h2></div></div><p class="caption">示例累计代价 / 秒 · 越低越好</p><div id="strategy-bars"></div><div id="strategy-story" class="result-story"></div><details class="assumptions"><summary>展开假设与计算方式</summary><p>统一进站代价 20 秒 + 暖胎 1.2 秒。延后 1 圈：另加 d；延后 3 圈：另加 d + 2d + 3d。交通损失分别为 t、t × f、t × f²。d、t、f 来自左侧设置。</p><p>这是教学用的简化代价模型，不是整场蒙特卡洛预测；没有包含能量、换胎延误、实际进站损失或事故概率，不能据此预测真实名次。</p></details></article><div class="panel insight-panel"><span class="eyebrow">TAKEAWAY</span><h3>没有脱离条件的“最好策略”。</h3><p class="body-copy section-space">试着把交通改成“不变”。当等待不能改善交通时，延后的额外轮胎损失会直接成为代价。</p><button class="text-button section-space" data-event="vsc">回看这个决策的来龙去脉${icon('arrow-right')}</button></div><button class="lab-teaser scene-teaser" data-view="3d"><img src="./assets/f1-two-cars-side.png" alt="两辆 F1 概念车侧面模型"><div><span class="eyebrow lime">SEE THE BATTLE</span><h3>从策略，走近攻防。</h3><p>进入三维侧面慢镜头 →</p></div></button></aside></div>`;$('#traffic-evolution').value=String(state.trafficFactor);updateStrategy();}
function updateStrategy(){const values=simulate();$('#deg-value').textContent=state.deg.toFixed(1)+' s / 圈';$('#traffic-value').textContent=state.traffic.toFixed(1)+' s';const max=Math.max(...values)*1.1;$('#strategy-bars').innerHTML=values.map((v,i)=>`<div class="comparison-row ${state.option===i?'selected':''}"><span>${optionNames[i]}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><strong>${v.toFixed(1)} s</strong></div>`).join('');const delta=values[state.option]-values[0];$('#strategy-story').innerHTML=`<span class="eyebrow">你选择了 · ${optionNames[state.option]}</span><h3>${state.option===0?'以实际进站时机作为比较基准':Math.abs(delta)<.05?'与基准代价接近':`在这些假设下，${delta<0?'少损失':'多损失'} ${Math.abs(delta).toFixed(1)} 秒`}</h3><p>${state.option===0?'这是模型中的基准代价，不是对实际换胎时间的复刻。选择另一条策略，比较等待是否值得。':delta<0?'模型中，改善交通省下的时间，大于旧胎额外损失。只有交通确实改善，等待才可能划算。':'模型中，等待的收益不足以抵消额外代价。改变轮胎或交通假设，结论也可能改变。'}</p>`;$$('[data-option]').forEach(b=>{b.classList.toggle('selected',+b.dataset.option===state.option);b.setAttribute('aria-pressed',String(+b.dataset.option===state.option));});}
function render3d(){if($('#page-3d').childElementCount)return;$('#page-3d').innerHTML=heading('BATTLE IN THREE DIMENSIONS','贴近赛车，看清每一次攻防。','拖动观察角度，放慢时间，看见双车位置如何变化。')+`<div class="scene-shell" id="battle-scene"><div class="scene-header"><strong>DOUBLE-CAR BATTLE / 双车攻防</strong><span class="chip orange">通用模型 · 非赛事轨迹</span></div><div class="scene-stage" id="scene-stage"><div class="scene-loading" id="scene-loading"><img src="./assets/f1-two-cars-side.png" alt="双车侧视模型预览"><span>正在载入双车三维模型…</span></div><div class="scene-driver" id="car-a-label" hidden>A / 进攻方</div><div class="scene-driver b" id="car-b-label" hidden>B / 防守方</div></div><div class="scene-controls"><div class="segmented" aria-label="观看角度"><button data-camera="front" class="active" disabled>侧前方</button><button data-camera="side" disabled>纯侧面</button><button data-camera="rear" disabled>侧后方</button></div><div class="segmented" aria-label="攻防阶段"><button data-progress="12" disabled>01 接近</button><button data-progress="50" disabled>02 并排</button><button data-progress="88" disabled>03 前出</button></div></div><div class="scene-transport"><button id="scene-play" class="button primary" disabled>播放回合</button><div class="scene-playbar"><label class="range-label" for="scene-progress"><span>攻防进度</span><span id="scene-phase">接近</span></label><input id="scene-progress" type="range" class="range" min="0" max="100" value="12" aria-label="攻防进度" disabled></div><select id="scene-speed" class="select" aria-label="播放速度" disabled><option value="0.25">0.25× · 逐步观察</option><option value="0.5" selected>0.5× · 慢镜头</option><option value="1">1× · 正常演示</option></select></div><div class="scene-readout"><span>拖动旋转 · 滚动缩放 · 保持贴近地面的视角</span><span>CONCEPT CARS / ILLUSTRATIVE MOTION</span></div></div><div class="moment-grid section-space"><div class="track-note"><span class="chip orange">01 / 接近</span><h3>看到追赶的过程</h3><p>进攻方从落后逐步接近。模型展示相对位置，不把移动速度当作真实遥测。</p></div><div class="track-note"><span class="chip lime">02 / 并排</span><h3>注意车头与后轴的位置</h3><p>侧视能更直观地理解并排程度。是否享有弯角空间，还需结合适用规则与具体情境。</p></div><div class="track-note"><span class="chip blue">03 / 前出</span><h3>向下一段攻防延伸</h3><p>这一版演示基础位置变化。真实弯道走线、制动点和轨迹校准是后续的数据接入目标。</p></div></div><p class="caption">这段三维动画是可旋转的真实模型渲染，运动为教学示意；不声称还原所选赛事的真实赛道或车手精确轨迹。</p>`;}
function renderSaved(){$('#page-saved').innerHTML=heading('YOUR RACE NOTES','值得再看一次的瞬间。','收藏你想在复盘与讨论中继续研究的赛点。')+(bookmarks.length?`<div class="moment-grid">${cards(allMoments.filter(m=>bookmarks.includes(m.id)).map(m=>({...m,phase:races.find(r=>r.id===m.race).short+' · '+m.phase})))}</div><p class="caption">进入赛点，点击右上角书签即可取消收藏。收藏保存在当前浏览器。</p>`:`<div class="empty-state">${icon('bookmark')}<h2>给精彩留一个位置。</h2><p>在赛点分析中点击书签，就能把这个瞬间留在这里。</p><button class="button primary" data-view="moments">去发现第一个赛点${icon('arrow-up-right')}</button></div>`);}
