function toggleBookmark(id){bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];try{localStorage.setItem('apex-bookmarks-v1',JSON.stringify(bookmarks));toast(bookmarks.includes(id)?'已收藏，去“我的赛点”继续查看。':'已取消收藏。');}catch{toast('已在当前页面收藏，浏览器暂不支持保存。');}$('.saved-count').textContent=bookmarks.length;if(state.view==='moments'){renderMoment();$('#page-moments').insertAdjacentHTML('afterbegin',customEntry());}icons();}
