 $('.hero-copy h2').innerHTML=r.headline;$('.hero-copy p').textContent=r.summary;
 const cta=$('.hero-actions .primary');delete cta.dataset.view;cta.dataset.event=r.highlight?.id||'launch';
 const data=$$('.hero-bottom>div');data[0].innerHTML=`<span>RACE DISTANCE</span><strong>${r.laps}<small>圈</small></strong>`;
 data[1].innerHTML=`<span>RACE WINNER</span><strong>${r.podium[0][1].split(' ').slice(-1)[0].toUpperCase()}<small>${r.podium[0][2]}</small></strong>`;
 const delta=parseFloat(r.podium[2][3].replace('+',''))-parseFloat(r.podium[1][3].replace('+',''));
 data[2].innerHTML=`<span>P2 ↔ P3 · 完赛差距</span><strong>${delta.toFixed(3)}<small>秒</small></strong>`;$('.hero-number').textContent=String(r.round).padStart(2,'0');
 const credit=$('#photo-credit');credit.href=r.photoSource;credit.textContent='赛事图片 · Formula1.com ↗';credit.title=r.caption;
