 if($('#hero-photo').dataset.asset!==target){const version=++photoVersion;hero.classList.add('is-loading');delete $('#hero-photo').dataset.asset;$('#hero-photo').style.backgroundImage='none';let status=$('.hero-photo-status');if(!status){status=document.createElement('span');status.className='hero-photo-status';status.setAttribute('role','status');hero.append(status);}status.hidden=false;status.textContent='正在载入本场精彩瞬间…';const photo=new Image();photo.onload=()=>{if(version!==photoVersion)return;$('#hero-photo').style.backgroundImage=`url("${target}")`;$('#hero-photo').dataset.asset=target;hero.classList.remove('is-loading');status.hidden=true;};photo.onerror=()=>{if(version!==photoVersion)return;status.textContent='图片暂未载入，可查看右下角官方图片来源。';};photo.src=target;}
