function renderArchiveStrategy(){const r=currentRace(),m=r.highlight;$('#strategy-cases').innerHTML=caseHeading('精选案例',m.title,`${r.name} · ${r.city} · ${r.date}`)+`<div class="two-col"><article class="panel"><span class="chip lime">${r.short}站 · 决策取舍</span><div class="stack section-space"><div class="evidence-row"><h3>发生了什么</h3><p>${m.fact}</p></div><div class="evidence-row"><h3>为什么值得讨论</h3><p>${m.why}</p></div><div class="evidence-row"><h3>其他选择可能改变什么</h3><p>${m.alternative}</p></div></div><p class="caption">${raceLink(r)} · 原因与备选路径是公开信息基础上的解读。</p><div class="action-row"><button class="button primary" data-view="3d">${icon('box')}三维观察攻防关系</button></div></article><aside class="panel"><span class="eyebrow lime">INTERACTIVE EXAMPLE</span><h2>亲自改变一次策略条件</h2><p class="body-copy section-space">在研究院带入本场车手的轮胎与圈次，比较进站和攻防选择。也可以打开西班牙站的 VSC 教学案例。</p><div class="action-row"><button class="button primary" data-view="strategy-research">用本场数据开始推演</button><button class="button" data-action="madrid-lab">西班牙 VSC 教学案例${icon('arrow-up-right')}</button></div></aside></div>`;}
function renderRaceSource(){const r=currentRace();let section=$('#current-race-source');if(!section){section=document.createElement('div');section.id='current-race-source';$('#sources-content').prepend(section);}section.innerHTML=`<h3>当前选中 · ${r.name} / ${r.date}</h3><p>${r.caption}。<a href="${r.photoSource}" target="_blank" rel="noreferrer">本场图片出处 ↗</a> · ${raceLink(r)} · <a href="${calendarSource}" target="_blank" rel="noreferrer">最近十场排序依据 ↗</a></p>`;}

$('#sources-content').innerHTML=`<div class="source-note">本 Demo 收录截至 2026 年 9 月 19 日最近十场已完赛大奖赛，默认打开最新的西班牙站。精选瞬间由编辑挑选；赛事列表目前是固定样本，不自动刷新。</div><h3>01 / 可追溯的赛事事实</h3><p>比赛结果、赛点叙事和照片来自赛事官方及车队报道。自定义赛点使用 <a href="https://openf1.org/docs/" target="_blank" rel="noreferrer">OpenF1 公开历史记录 ↗</a>，每项数据可在分析页核对出处。西班牙站深度样本依据：${source('FIA 结果与报告')}、${source('F1 正赛报告','race')}、${source('McLaren 赛后报告','team')}。</p><h3>02 / 有边界的策略解读</h3><p>“为什么”部分依据公开事实解释约束与取舍，不等于掌握了车队内部决策过程。未接入车队无线电、内部仿真、实时功率或下压力。</p><h3>03 / 可以操作的演示推演</h3><p>策略实验室使用可见的简化公式，车手数据页曲线使用合成数据；自定义赛点中的历史圈速、轮胎段和间隔记录来自 OpenF1，精确弯角轨迹尚未接入。三维部分是 Blender 创建的两辆通用 F1 概念车，使用示意运动。它们用于验证体验，不构成真实比赛预测或精确重建。</p><h3>04 / 图片与模型</h3><p>十场海报分别使用本场真实赛事图片。默认海报为 2026 西班牙大奖赛发车阶段的 Norris 与 Antonelli。${source('Formula1.com 原文与图片来源','photo')}。原页版权归 Formula One World Championship Limited；未确认图片复用许可。本站为非官方学习与交流 Demo。</p><p>双车模型为本项目生成，可作为继续开发的初始素材。</p>`;
$('#overview-moments').innerHTML=cards(moments);$('.saved-count').textContent=bookmarks.length;
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('.brand')){e.preventDefault();navigate('overview');}if(b.dataset.race){selectRace(b.dataset.race);return;}if(b.dataset.raceScroll){$('#race-rail').scrollBy({left:Number(b.dataset.raceScroll)*440,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.openCase)$('#strategy-legacy').open=true;if(b.dataset.event)setEvent(b.dataset.event);if(b.dataset.bookmark)toggleBookmark(b.dataset.bookmark);if(b.dataset.driver){state.driver=b.dataset.driver;if(state.compare===state.driver)state.compare=drivers.find(d=>d.id!==state.driver).id;renderDrivers();icons();}if(b.dataset.option!==undefined){state.option=+b.dataset.option;updateStrategy();}switch(b.dataset.action){case'sources':renderRaceSource();$('#sources-dialog').showModal();break;case'close-sources':$('#sources-dialog').close();break;case'madrid-lab':selectRace('spain',false);navigate('strategy-research');$('#strategy-legacy').open=true;break;case'reset-strategy':Object.assign(state,{option:1,deg:.8,traffic:3,trafficFactor:.4});renderStrategyCase();icons();break;}});
document.addEventListener('input',e=>{if(e.target.id==='deg-slider'){state.deg=+e.target.value;updateStrategy();}if(e.target.id==='traffic-slider'){state.traffic=+e.target.value;updateStrategy();}});
document.addEventListener('change',e=>{if(e.target.id==='beginner-toggle'){state.beginner=e.target.checked;renderMoment();$('#page-moments').insertAdjacentHTML('afterbegin',customEntry());icons();}if(e.target.id==='compare-driver'){state.compare=e.target.value;renderDrivers();icons();}if(e.target.id==='traffic-evolution'){state.trafficFactor=+e.target.value;updateStrategy();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'overview'));
window.addEventListener('load',icons);
const initialRace=new URLSearchParams(location.search).get('race');if(races.some(r=>r.id===initialRace))selectRace(initialRace,false);else renderOverview();
const legacyCases=new URLSearchParams(location.search).get('lab')==='cases';
navigate(legacyCases?'strategy-research':names[location.hash.slice(1)]?location.hash.slice(1):'overview');
if(legacyCases)$('#strategy-legacy').open=true;
// Optional WebMCP uses the same navigation and simulation state as the visible controls.
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'query_custom_racepoint',title:'分析自定义赛点',description:'Compare public historical evidence at a selected driver lap start. The corner is a research label only; no corner trajectory or private team intent is inferred.',inputSchema:{type:'object',properties:{race:{type:'string',enum:races.map(r=>r.id)},driver:{type:'string'},opponent:{type:'string'},lap:{type:'integer',minimum:1,maximum:78},corner:{type:'integer',minimum:1,maximum:30}},required:['race','driver','opponent','lap','corner'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){const evidence=await prepareCustomAnalysis(input,races);selectRace(input.race,false);state.labRevision++;navigate('custom');await customReady;return {...input,...evidence};}});register({name:'select_recent_race',title:'选择最近十场比赛',description:'Select a completed Grand Prix and update its poster, results and highlight in the overview.',inputSchema:{type:'object',properties:{race:{type:'string',enum:races.map(r=>r.id)}},required:['race'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!races.some(r=>r.id===input.race))throw new Error('Unknown race');selectRace(input.race);return{race:state.race,title:currentRace().name,view:state.view};}});register({name:'navigate_racecraft',title:'打开 F1 Racecraft 页面',description:'Navigate to an existing F1 Racecraft demo view and optionally select a race highlight.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(names)},event:{type:'string',enum:allMoments.map(m=>m.id)}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||!names[input.view]||Object.keys(input).some(k=>!['view','event'].includes(k))||(input.event&&!allMoments.some(m=>m.id===input.event)))throw new Error('Invalid view or event');if(input.event){const m=allMoments.find(m=>m.id===input.event);selectRace(m.race,false);state.event=input.event;}navigate(input.view);return{view:state.view,event:state.event,race:state.race};}});register({name:'configure_strategy_demo',title:'比较策略假设',description:'Set teaching-model assumptions, open the strategy lab, and return illustrative costs in seconds. Results are not race predictions.',inputSchema:{type:'object',properties:{option:{type:'integer',minimum:0,maximum:2},degradation:{type:'number',minimum:.1,maximum:2},traffic:{type:'number',minimum:0,maximum:8},trafficFactor:{type:'number',enum:[.4,1,1.4]}},required:['option','degradation','traffic','trafficFactor'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length!==4||!Number.isInteger(input.option)||input.option<0||input.option>2||!Number.isFinite(input.degradation)||input.degradation<.1||input.degradation>2||!Number.isFinite(input.traffic)||input.traffic<0||input.traffic>8||![.4,1,1.4].includes(input.trafficFactor))throw new Error('Invalid simulation assumptions');selectRace('spain',false);Object.assign(state,{option:input.option,deg:Math.round(input.degradation*10)/10,traffic:Math.round(input.traffic*2)/2,trafficFactor:input.trafficFactor});navigate('strategy-research');$('#strategy-legacy').open=true;renderStrategyCase();return{synthetic:true,costsSeconds:simulate().map(x=>+x.toFixed(1)),selectedOption:state.option};}});}
